# Gracefully terminates all natively running Stage 4 background processes.

Write-Host "Stopping all running microservice processes..." -ForegroundColor Yellow

if (Test-Path ".services.pids") {
    $pids = Get-Content ".services.pids"
    foreach ($pid_val in $pids) {
        $pid_val = $pid_val.Trim()
        if ($pid_val) {
            try {
                $process = Get-Process -Id $pid_val -ErrorAction SilentlyContinue
                if ($process) {
                    Write-Host "Killing process $pid_val ($($process.ProcessName))..." -ForegroundColor Cyan
                    Stop-Process -Id $pid_val -Force
                }
            } catch {
                Write-Host "Failed to stop process $pid_val: $_" -ForegroundColor Red
            }
        }
    }
    Remove-Item ".services.pids" -Force -ErrorAction SilentlyContinue
    Write-Host "All background service processes stopped." -ForegroundColor Green
} else {
    Write-Host "No active service PID file found. Checking for any orphaned uvicorn/python processes on ports..." -ForegroundColor Yellow
}

# General cleanup of any uvicorn endpoints on our ports (just in case)
$ports = @(18600, 18601, 18602, 18603)
foreach ($port in $ports) {
    try {
        $connections = Get-NetTCPConnection -LocalPort $port -State Listen -ErrorAction SilentlyContinue
        foreach ($conn in $connections) {
            $procId = $conn.OwningProcess
            if ($procId) {
                Write-Host "Cleaning up process $procId listening on port $port..." -ForegroundColor Cyan
                Stop-Process -Id $procId -Force -ErrorAction SilentlyContinue
            }
        }
    } catch {
        # Silent pass
    }
}

Write-Host "Done cleanup." -ForegroundColor Green

